{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise TypeError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("case requires nodes and required_symbols")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list):
        raise TypeError("nodes must be an array")
    if not isinstance(required_symbols, list) or not all(isinstance(s, str) for s in required_symbols):
        raise TypeError("required_symbols must be an array of strings")

    by_id = {}
    required_fields = ("id", "parent", "symbol", "depth", "removable", "utility")
    for node in nodes:
        if not isinstance(node, dict):
            raise TypeError("each node must be an object")
        if any(field not in node for field in required_fields):
            raise ValueError("each node requires id, parent, symbol, depth, removable, and utility")

        node_id = node["id"]
        parent = node["parent"]
        depth = node["depth"]
        utility = node["utility"]
        if not isinstance(node_id, str) or not isinstance(node["symbol"], str):
            raise TypeError("node id and symbol must be strings")
        if parent is not None and not isinstance(parent, str):
            raise TypeError("node parent must be a string or null")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise TypeError("node depth must be a nonnegative integer")
        if not isinstance(node["removable"], bool):
            raise TypeError("node removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise TypeError("node utility must be a finite number")
        if node_id in by_id:
            raise ValueError("node ids must be unique")
        by_id[node_id] = node

    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1 or roots[0]["depth"] != 0:
        raise ValueError("nodes must contain exactly one depth-zero root")
    root_id = roots[0]["id"]

    for node in nodes:
        parent_id = node["parent"]
        if parent_id is not None:
            if parent_id not in by_id:
                raise ValueError("every parent must reference an existing node")
            if by_id[parent_id]["depth"] + 1 != node["depth"]:
                raise ValueError("node depths must agree with parent relationships")

    required = set(required_symbols)
    symbol_counts = {}
    for node in nodes:
        symbol = node["symbol"]
        symbol_counts[symbol] = symbol_counts.get(symbol, 0) + 1
    if any(symbol_counts.get(symbol, 0) == 0 for symbol in required):
        raise ValueError("every required symbol must be represented")

    retained = set(by_id)
    removed = []
    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))

    for node in candidates:
        node_id = node["id"]
        symbol = node["symbol"]
        if node_id == root_id or not node["removable"] or symbol in required:
            continue
        if any(other["parent"] == node_id and other["id"] in retained for other in nodes):
            continue

        symbol_counts[symbol] -= 1
        if any(symbol_counts.get(required_symbol, 0) == 0 for required_symbol in required):
            symbol_counts[symbol] += 1
            continue

        retained.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
